__global__ void conv3d_custom_kernel(
    const float* input, const float* weight, const float* bias, float* output,
    int batch_size, int input_channels, int D_in, int H_in, int W_in,
    int output_channels, int kernel_d, int kernel_h, int kernel_w,
    int D_out, int H_out, int W_out
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int total = batch_size * output_channels * D_out * H_out * W_out;

    if (idx < total) {
        const int n = idx / (output_channels * D_out * H_out * W_out);
        int rem = idx % (output_channels * D_out * H_out * W_out);
        const int c = rem / (D_out * H_out * W_out);
        rem = rem % (D_out * H_out * W_out);
        const int d = rem / (H_out * W_out);
        rem = rem % (H_out * W_out);
        const int h = rem / W_out;
        const int w = rem % W_out;

        float acc = 0.0f;
        for (int ci = 0; ci < input_channels; ++ci) {
            for (int kd = 0; kd < kernel_d; ++kd) {
                const int dz = d * 1 + kd - 0; // stride=1, padding=0
                if (dz < 0 || dz >= D_in) continue;
                for (int kh = 0; kh < kernel_h; ++kh) {
                    const int hz = h * 1 + kh - 0; 
                    if (hz < 0 || hz >= H_in) continue;
                    for (int kw = 0; kw < kernel_w; ++kw) {
                        const int wz = w * 1 + kw - 0;
                        if (wz < 0 || wz >= W_in) continue;

                        const int inp_idx = n * input_channels * D_in * H_in * W_in
                            + ci * D_in * H_in * W_in
                            + dz * H_in * W_in
                            + hz * W_in + wz;

                        const int weight_idx = c * input_channels * kernel_d * kernel_h * kernel_w
                            + ci * kernel_d * kernel_h * kernel_w
                            + kd * kernel_h * kernel_w + kh * kernel_w + kw;

                        acc += input[inp_idx] * weight[weight_idx];
                    }
                }
            }
        }

        if (bias != nullptr) {
            acc += bias[c];
        }

        output[idx] = acc;
    }
}

torch::Tensor conv3d_custom(
    torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
    int kernel_d, int kernel_h, int kernel_w,
    int D_out, int H_out, int W_out
) {
    const int batch_size = input.size(0);
    const int input_channels = input.size(1);
    const int D_in = input.size(2);
    const int H_in = input.size(3);
    const int W_in = input.size(4);
    const int output_channels = weight.size(0);

    auto output = torch::zeros({batch_size, output_channels, D_out, H_out, W_out}, input.options());

    const int threads = 256;
    const int blocks = (batch_size * output_channels * D_out * H_out * W_out + threads - 1) / threads;

    hipStream_t stream = at::hip::getCurrentHIPStream().stream();

    conv3d_custom_kernel<<<blocks, threads, 0, stream>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        (bias.defined() && bias.numel() > 0) ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size,
        input_channels,
        D_in,
        H_in,
        W_in,
        output_channels,
        kernel_d,
        kernel_h,
        kernel_w,
        D_out,
        H_out,
        W_out
    );

    return output;
}

