#define TILE_SIZE 16
#define THREADS_PER_BLOCK 256

__global__ void matmul_kernel(const float* __restrict__ A, 
                              const float* __restrict__ B,
                              float* __restrict__ C,
                              int M, int N, int K) {

    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    float acc = 0.0;

    for (int t = 0; t < (K + TILE_SIZE - 1)/TILE_SIZE; ++t) {
        int aCol = t * TILE_SIZE + threadIdx.x;
        int bRow = t * TILE_SIZE + threadIdx.y;

        if(row < M && aCol < K) As[threadIdx.y][threadIdx.x] = A[row*K + aCol];
        else As[threadIdx.y][threadIdx.x] = 0.0f;

        if(col < N && bRow < K) Bs[threadIdx.y][threadIdx.x] = B[bRow*N + col];
        else Bs[threadIdx.y][threadIdx.x] = 0.0f;

        __syncthreads();

        #pragma unroll
        for(int k = 0; k < TILE_SIZE; ++k) {
            acc += As[threadIdx.y][k] * Bs[k][threadIdx.x];
        }
        __syncthreads();
    }

    if(row < M && col < N) {
        C[row*N + col] = acc;
    }
}

torch::Tensor matmul_rocm(torch::Tensor A, torch::Tensor B) {
    int M = A.size(0);
